IMU_SILENT_S = 1.0         # no IMU message for this long → "silent" in the status values


# from mission 09 — finished: read it, use it, do not change it
def naive_sigma(est):
    """v0's σ: √max(a, c) straight from the numbers — whatever the covariance type, even if they are no
    covariance at all, even if they are all zero (that is the hole). A negative variance counts as 0.

    Example: naive_sigma(Estimate("gps", 35.8, 10.6, 0.0, cov=(0.0,) * 9)) → 0.0   (a σ of 0 m: "perfect")
    """
    a, _, c = horizontal(est.cov)
    return math.sqrt(max(a, c, 0.0))


# from mission 09 — finished: read it, use it, do not change it
class NaiveJudge:
    """The decision logic of arbiter v0, without ROS (so it can be tested with plain Python).

    receive(est, now_s) stores the newest estimate of each source (a GPS fix only if the jump gate accepts
    it) and returns (stored, reason). decide(now_s) returns a dict: state, source (None if none), estimate,
    sigma_m, reason, sources (source → "eligible" or why not).
    Example: j = NaiveJudge(DEFAULTS); j.decide(0.0)["state"] → "STARTING"
    """

    def __init__(self, cfg, use_eligible=False):
        self.cfg = dict(cfg)
        self.use_eligible = bool(use_eligible)
        if self.use_eligible and not hasattr(estimate, "eligible"):
            raise ValueError("use_eligible needs estimate.eligible() and estimate.stated_sigma() (mission 12)")
        self.gate = JumpGate(self.cfg)
        self.latest = {}               # source → its newest stored Estimate
        self.refused = {}              # source → the reason of its last refusal

    def receive(self, est, now_s):
        est.t_recv_s = now_s
        if est.source not in TIMEOUT_KEY:
            return False, f"unknown source {est.source!r}"
        if est.source == "gps" and est.valid and is_finite_latlon(est.lat, est.lon):
            ok, why = self.gate.check(est)
            if not ok:
                self.refused["gps"] = "refused: " + why
                return False, why
        self.refused.pop(est.source, None)
        self.latest[est.source] = est
        return True, "stored"

    def usable(self, est, now_s):
        """(ok, why) for one stored estimate: v0's naive test, or the student's eligible() (use_eligible)."""
        if self.use_eligible:
            got = estimate.eligible(est, now_s, self.cfg)
            if not (isinstance(got, tuple) and len(got) == 2):
                return False, f"eligible() returned {got!r}, not (ok, reason)"
            return bool(got[0]), str(got[1])
        if not est.valid:
            return False, "no position"
        if not is_finite_latlon(est.lat, est.lon):
            return False, "bad position"
        age = now_s - est.stamp_s
        timeout = float(self.cfg[TIMEOUT_KEY[est.source]])
        if age > timeout:
            return False, f"stale ({age:.1f} s > {timeout:.1f} s)"
        return True, "eligible"

    def sigma(self, est):
        """The σ used to classify: naive_sigma(), or the student's stated_sigma() (use_eligible)."""
        if self.use_eligible:
            s = estimate.stated_sigma(est, self.cfg)
            return float(s) if isinstance(s, (int, float)) and not isinstance(s, bool) else None
        return naive_sigma(est)

    def decide(self, now_s):
        sources, winner = {}, None
        for name in SOURCES:
            est = self.latest.get(name)
            if est is None:
                sources[name] = self.refused.get(name, "nothing received")
                continue
            ok, why = self.usable(est, now_s)
            sources[name] = why + (f"; last fix {self.refused[name]}" if name in self.refused else "")
            if ok and winner is None:
                winner = est
        if not self.latest:
            return {"state": "STARTING", "source": None, "estimate": None, "sigma_m": None,
                    "reason": "no position received yet", "sources": sources}
        if winner is None:
            why = "; ".join(f"{n}: {sources[n]}" for n in SOURCES if sources[n] != "nothing received")
            return {"state": "NO_FIX", "source": None, "estimate": None, "sigma_m": None,
                    "reason": "no usable source (" + why + ")", "sources": sources}
        sigma = self.sigma(winner)
        state, why = classify(sigma, self.cfg)
        return {"state": state, "source": winner.source, "estimate": winner, "sigma_m": sigma,
                "reason": f"{winner.source}: {why}", "sources": sources}


